/* Offset the cutout's transparent foot so her hands rest over the panel edge. */
@media(min-width:601px){
  .reference.reference-inline{overflow:visible}
  .reference.reference-inline>.jeeves-corner-cutout{margin-bottom:calc(-1 * clamp(24px,3.4vw,48px));transform:translateY(10%)}
}

